import{_ as e,o as t,c as o,a2 as c}from"./chunks/framework.dMg474VA.js";const u=JSON.parse('{"title":"RLGW API Reference","description":"","frontmatter":{},"headers":[],"relativePath":"api.md","filePath":"api.md"}'),a={name:"api.md"};function r(i,d,n,s,l,h){return t(),o("div",null,[...d[0]||(d[0]=[c('<h1 id="rlgw-api-reference" tabindex="-1">RLGW API Reference <a class="header-anchor" href="#rlgw-api-reference" aria-label="Permalink to &quot;RLGW API Reference&quot;">​</a></h1><p>This document details the public data-plane and control-plane endpoints exposed by the Rate-Limit Gateway.</p><hr><h2 id="_1-data-plane-listener-default-port-8080" tabindex="-1">1. Data Plane Listener (Default Port: 8080) <a class="header-anchor" href="#_1-data-plane-listener-default-port-8080" aria-label="Permalink to &quot;1. Data Plane Listener (Default Port: 8080)&quot;">​</a></h2><p>All application traffic routes through the data-plane listener.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path Pattern</th><th>Description</th><th>Headers &amp; Semantics</th></tr></thead><tbody><tr><td><code>ANY</code></td><td><code>/*</code> (routes matching <code>upstreams</code>)</td><td>Reverse-proxied upstream request subject to rate limiting policies</td><td><strong>Headers In:</strong> <code>X-Request-Id</code>, <code>X-Client-Id</code>, <code>X-Tenant-Id</code>, <code>Cost</code><br><strong>Headers Out:</strong> <code>RateLimit-Limit</code>, <code>RateLimit-Remaining</code>, <code>RateLimit-Reset</code>, <code>RateLimit-Policy</code>, <code>X-RateLimit-*</code>, <code>X-Request-Id</code>, <code>Via</code></td></tr><tr><td><code>ANY</code></td><td>Any rate-limited path</td><td>Denied when budget is exhausted</td><td>Returns <strong>HTTP 429 Too Many Requests</strong> with <code>Retry-After: &lt;seconds&gt;</code>, <code>Cache-Control: no-store</code>, and structured JSON or Problem+JSON body</td></tr><tr><td><code>GET</code></td><td>Upstream timeout</td><td>Triggered when upstream exceeds deadline</td><td>Returns <strong>HTTP 504 Gateway Timeout</strong></td></tr><tr><td><code>GET</code></td><td>Upstream connection failure</td><td>Triggered on connection refused or reset</td><td>Returns <strong>HTTP 502 Bad Gateway</strong></td></tr><tr><td><code>UPGRADE</code></td><td><code>/*</code></td><td>WebSocket / HTTP upgrade connection</td><td>Bi-directional streaming pipe with hop-by-hop handling</td></tr></tbody></table><hr><h2 id="_2-admin-plane-listener-default-port-8081" tabindex="-1">2. Admin Plane Listener (Default Port: 8081) <a class="header-anchor" href="#_2-admin-plane-listener-default-port-8081" aria-label="Permalink to &quot;2. Admin Plane Listener (Default Port: 8081)&quot;">​</a></h2><p>All health probes, metrics, and administration APIs route through the admin-plane listener.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Auth Required</th><th>Description</th><th>Status Codes</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/healthz</code></td><td>No</td><td>Process liveness &amp; event loop lag probe (<code>monitorEventLoopDelay</code>)</td><td><code>200 OK</code> (healthy), <code>503 Service Unavailable</code> (stalled loop)</td></tr><tr><td><code>GET</code></td><td><code>/readyz</code></td><td>No</td><td>Gateway readiness probe; returns 503 during graceful shutdown</td><td><code>200 OK</code> (ready), <code>503 Service Unavailable</code> (draining/not ready)</td></tr><tr><td><code>GET</code></td><td><code>/metrics</code></td><td>No</td><td>Prometheus text exposition format metrics</td><td><code>200 OK</code> (<code>text/plain; version=0.0.4</code>)</td></tr><tr><td><code>GET</code></td><td><code>/admin/v1/snapshot</code></td><td>Yes (Admin Token)</td><td>Returns active policy snapshot metadata and content hash</td><td><code>200 OK</code>, <code>401 Unauthorized</code></td></tr><tr><td><code>POST</code></td><td><code>/admin/v1/reload</code></td><td>Yes (Admin Token)</td><td>Triggers atomic reload of policies from storage</td><td><code>200 OK</code>, <code>401 Unauthorized</code>, <code>500 Server Error</code></td></tr><tr><td><code>GET</code></td><td><code>/admin/v1/policies</code></td><td>Yes (Admin Token)</td><td>Lists active policies with tenant filtering and ETag caching</td><td><code>200 OK</code>, <code>304 Not Modified</code>, <code>401 Unauthorized</code></td></tr><tr><td><code>GET</code></td><td><code>/admin/v1/policies/:id</code></td><td>Yes (Admin Token)</td><td>Fetches detail of an individual rate limiting policy</td><td><code>200 OK</code>, <code>404 Not Found</code>, <code>401 Unauthorized</code></td></tr><tr><td><code>GET</code></td><td><code>/admin/v1/policies/:id/diff</code></td><td>Yes (Admin Token)</td><td>Semantic field-level diff between policy versions with inheritance provenance</td><td><code>200 OK</code>, <code>401 Unauthorized</code></td></tr><tr><td><code>GET</code></td><td><code>/admin/v1/counters?key=&lt;key&gt;</code></td><td>Yes (Admin Token)</td><td>Store introspection: evaluates current budget via <code>peek</code> (strict tenant scope)</td><td><code>200 OK</code>, <code>400 Bad Request</code>, <code>401 Unauthorized</code></td></tr><tr><td><code>GET</code></td><td><code>/admin/v1/upstreams</code></td><td>Yes (Admin Token)</td><td>Circuit breaker and route health statuses</td><td><code>200 OK</code>, <code>401 Unauthorized</code></td></tr><tr><td><code>POST</code></td><td><code>/admin/v1/evaluate</code></td><td>Yes (Admin Token)</td><td>Semantic dry-run simulation against virtual clock &amp; isolated in-memory store</td><td><code>200 OK</code>, <code>401 Unauthorized</code></td></tr><tr><td><code>POST</code></td><td><code>/admin/v1/validate</code></td><td>Yes (Admin Token)</td><td>Policy syntax &amp; schema validation against Zod schema</td><td><code>200 OK</code>, <code>400 Bad Request</code>, <code>401 Unauthorized</code></td></tr><tr><td><code>POST</code></td><td><code>/admin/v1/quotas/import</code></td><td>Yes (Admin Token)</td><td>Bulk import tenant quotas with validation report</td><td><code>200 OK</code>, <code>400 Bad Request</code>, <code>401 Unauthorized</code></td></tr><tr><td><code>GET</code></td><td><code>/admin/v1/quotas/export</code></td><td>Yes (Admin Token)</td><td>Bulk export tenant quotas as JSON or CSV</td><td><code>200 OK</code>, <code>401 Unauthorized</code></td></tr><tr><td><code>POST</code></td><td><code>/admin/v1/overrides</code></td><td>Yes (Admin Token)</td><td>Dynamic quota override with TTL and relaxation guardrails</td><td><code>200 OK</code>, <code>401 Unauthorized</code></td></tr><tr><td><code>POST</code></td><td><code>/admin/v1/allowlist</code></td><td>Yes (Admin Token)</td><td>Temporary emergency allowlist with required reason and auto-expiry</td><td><code>200 OK</code>, <code>400 Bad Request</code>, <code>401 Unauthorized</code></td></tr><tr><td><code>POST</code></td><td><code>/admin/v1/blacklist</code></td><td>Yes (Admin Token)</td><td>Dynamic client/CIDR blacklist with pubsub propagation</td><td><code>200 OK</code>, <code>401 Unauthorized</code></td></tr><tr><td><code>POST</code></td><td><code>/admin/v1/loglevel</code></td><td>Yes (Admin Token)</td><td>Runtime log-level adjustment with auto-revert timer</td><td><code>200 OK</code>, <code>401 Unauthorized</code></td></tr><tr><td><code>POST</code></td><td><code>/admin/v1/approvals</code></td><td>Yes (Admin Token)</td><td>Propose policy change under two-person approval workflow</td><td><code>200 OK</code>, <code>401 Unauthorized</code></td></tr><tr><td><code>PUT</code></td><td><code>/admin/v1/approvals/:id</code></td><td>Yes (Admin Token)</td><td>Approve pending policy change (enforces distinct proposer/approver)</td><td><code>200 OK</code>, <code>403 Forbidden</code>, <code>401 Unauthorized</code></td></tr></tbody></table>',10)])])}const m=e(a,[["render",r]]);export{u as __pageData,m as default};
